     * @return int table offset
     */
    public static function endQRP(FlatBufferBuilder $builder)
    {
        $o = $builder->endObject();
        return $o;
    }

    public static function finishQRPBuffer(FlatBufferBuilder $builder, $offset)
    {
        $builder->finish($offset, "$QRP");
    }
}
